# Review package: 0a953c6..HEAD

## Commits
a6adef7 Add basic greeting function

## Files changed
 greet.js      |  7 +++++++
 greet.test.js | 33 +++++++++++++++++++++++++++++++++
 2 files changed, 40 insertions(+)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..8755d92
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,7 @@
+function greet(name, options) {
+  const effectiveName = (name && typeof name === 'string' && name.trim()) ? name : 'Guest';
+  const format = (options && options.format) ? options.format : 'Hello, {name}!';
+  return format.replace('{name}', effectiveName);
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..4985ce3
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,33 @@
+const test = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet.js');
+
+test('greet with a valid name returns formatted greeting', () => {
+  const result = greet('Alice');
+  assert.strictEqual(result, 'Hello, Alice!');
+});
+
+test('greet with custom format returns custom formatted greeting', () => {
+  const result = greet('Bob', { format: 'Hi, {name}!' });
+  assert.strictEqual(result, 'Hi, Bob!');
+});
+
+test('greet with empty string returns default fallback', () => {
+  const result = greet('');
+  assert.strictEqual(result, 'Hello, Guest!');
+});
+
+test('greet with whitespace-only string returns default fallback', () => {
+  const result = greet('   ');
+  assert.strictEqual(result, 'Hello, Guest!');
+});
+
+test('greet with null returns default fallback', () => {
+  const result = greet(null);
+  assert.strictEqual(result, 'Hello, Guest!');
+});
+
+test('greet with undefined returns default fallback', () => {
+  const result = greet(undefined);
+  assert.strictEqual(result, 'Hello, Guest!');
+});
